function findMaxConsecutiveOnes(nums) {
  // Try every possible flip (or none) and measure the longest run directly.
  const longestRun = (arr) => {
    let longest = 0, run = 0;
    for (const v of arr) { run = v === 1 ? run + 1 : 0; longest = Math.max(longest, run); }
    return longest;
  };
  let answer = longestRun(nums);
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] === 0) {
      const copy = nums.slice();
      copy[i] = 1;
      answer = Math.max(answer, longestRun(copy));
    }
  }
  return answer;
}

